export enum RiskLevel {
  SAFE = 'SAFE',
  CAUTION = 'CAUTION',
  PREDATORY = 'PREDATORY',
  URGENT = 'URGENT',
}

export interface Clause {
  text: string;
  type: 'danger' | 'warning' | 'info';
  explanation: string;
}

export interface DocumentAnalysis {
  id: string;
  fileName: string;
  timestamp: number;
  summary: string;
  riskScore: number; // 0-100
  riskLevel: RiskLevel;
  clauses: Clause[];
  extractedAmounts: {
    label: string;
    amount: string;
  }[];
  actionableAdvice: string;
  rawText?: string;
}

export interface NegotiationTemplate {
  id: string;
  title: string;
  type: 'email' | 'script';
  content: string;
}

export interface SimulationScenario {
  name: string;
  incomeChange: number; // percentage
  expenseChange: number; // percentage
  inflationRate: number; // percentage
  months: number;
}

import { GoogleGenAI, Schema } from "@google/genai";
import { DocumentAnalysis, RiskLevel } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Helper to convert file to base64
export const fileToGenerativePart = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove data url prefix (e.g. "data:image/jpeg;base64,")
      const base64Data = base64String.split(',')[1];
      resolve(base64Data);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const analyzeDocument = async (file: File): Promise<DocumentAnalysis> => {
  const base64Data = await fileToGenerativePart(file);

  const model = "gemini-2.5-flash";

  const prompt = `
    Analyze this financial document image. Act as a predatory debt hunter and financial legal expert.
    Identify any predatory terms, high interest rates (calculate true APR if possible), hidden fees, rollover clauses, or dangerous legal stipulations.

    Return a JSON object with the following structure:
    {
      "summary": "A brief 2-sentence summary of what this document is.",
      "riskScore": 0 to 100 (where 100 is extremely predatory/dangerous),
      "riskLevel": "SAFE" | "CAUTION" | "PREDATORY" | "URGENT",
      "clauses": [
        { "text": "The exact text of the clause", "type": "danger" | "warning" | "info", "explanation": "Why this is bad in plain language" }
      ],
      "extractedAmounts": [
        { "label": "e.g. Total Due", "amount": "$100.00" }
      ],
      "actionableAdvice": "One paragraph of direct advice on what the user should do next."
    }

    Ensure the response is valid JSON. Do not use Markdown formatting in the JSON output if possible, but if you do, I will clean it.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: {
        parts: [
          { inlineData: { mimeType: file.type, data: base64Data } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text || "{}";
    const json = JSON.parse(text);

    return {
      id: crypto.randomUUID(),
      fileName: file.name,
      timestamp: Date.now(),
      ...json
    };

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw new Error("Failed to analyze document. Please try again.");
  }
};

export const generateNegotiationContent = async (
  docContext: DocumentAnalysis,
  type: 'email' | 'script' | 'letter',
  userGoal: string
): Promise<string> => {
  const model = "gemini-2.5-flash";

  const prompt = `
    Context: A user has analyzed a financial document with a risk level of ${docContext.riskLevel}.
    Summary of doc: ${docContext.summary}.
    Key dangerous clauses: ${docContext.clauses.filter(c => c.type === 'danger').map(c => c.text).join('; ')}.

    Task: Generate a ${type} for the user to negotiate with the issuer.
    User Goal: ${userGoal}

    Tone: Professional, firm, polite, but assertive. Cite consumer rights loosely if applicable (generic context).
    Format: Return just the text content of the ${type}.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt
    });
    return response.text || "Could not generate content.";
  } catch (error) {
    console.error("Gemini Negotiation Error:", error);
    return "Error generating negotiation content.";
  }
};

export const simulateScenarioAdvice = async (
  currentSavings: number,
  monthlyExpenses: number,
  scenario: string
): Promise<string> => {
   const model = "gemini-2.5-flash";
   const prompt = `
    You are a personal finance simulator.
    User Data:
    - Current Savings: $${currentSavings}
    - Monthly Expenses: $${monthlyExpenses}

    Scenario to Simulate: ${scenario}

    Provide a brief (3-4 sentences) analysis of how this scenario impacts their runway and risk exposure. Be realistic but helpful.
   `;

   try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt
    });
    return response.text || "Simulation analysis unavailable.";
   } catch (error) {
     return "Error running simulation analysis.";
   }
}

import React, { useRef, useState } from 'react';
import { Upload, Camera, FileText, Loader2, AlertTriangle } from 'lucide-react';
import { analyzeDocument } from '../services/geminiService';
import { DocumentAnalysis } from '../types';

interface DocumentScannerProps {
  onAnalysisComplete: (analysis: DocumentAnalysis) => void;
}

const DocumentScanner: React.FC<DocumentScannerProps> = ({ onAnalysisComplete }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    setError(null);

    try {
      const result = await analyzeDocument(file);
      onAnalysisComplete(result);
    } catch (err) {
      setError("Failed to analyze the document. Please try a clearer image.");
    } finally {
      setIsAnalyzing(false);
      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const triggerUpload = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="w-full max-w-2xl mx-auto p-6 bg-slate-800 rounded-xl border border-slate-700 shadow-xl">
      <div className="text-center mb-6">
        <h2 className="text-2xl font-bold text-white mb-2">Document Intake</h2>
        <p className="text-slate-400">Upload a bill, contract, or loan offer to detect hidden traps.</p>
      </div>

      <div 
        onClick={triggerUpload}
        className={`
          relative border-2 border-dashed rounded-xl p-10 
          flex flex-col items-center justify-center cursor-pointer 
          transition-all duration-200
          ${isAnalyzing ? 'border-blue-500 bg-slate-900/50' : 'border-slate-600 hover:border-emerald-500 hover:bg-slate-700/50'}
        `}
      >
        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleFileChange} 
          accept="image/*,.pdf" 
          className="hidden" 
        />

        {isAnalyzing ? (
          <div className="flex flex-col items-center animate-pulse">
            <Loader2 className="w-12 h-12 text-blue-500 animate-spin mb-4" />
            <p className="text-blue-400 font-semibold">AI is analyzing fine print...</p>
            <p className="text-slate-500 text-sm mt-2">Checking for predatory clauses</p>
          </div>
        ) : (
          <>
            <div className="flex space-x-4 mb-4">
              <div className="p-4 bg-slate-700 rounded-full text-emerald-400">
                <Camera size={32} />
              </div>
              <div className="p-4 bg-slate-700 rounded-full text-blue-400">
                <Upload size={32} />
              </div>
            </div>
            <p className="text-lg font-medium text-slate-200">Tap to Scan or Upload</p>
            <p className="text-sm text-slate-500 mt-2">Supports JPG, PNG</p>
          </>
        )}
      </div>

      {error && (
        <div className="mt-4 p-3 bg-red-900/30 border border-red-800 rounded-lg flex items-center gap-3 text-red-200">
          <AlertTriangle size={20} />
          <span>{error}</span>
        </div>
      )}
    </div>
  );
};

export default DocumentScanner;

import React, { useState } from 'react';
import { DocumentAnalysis, RiskLevel } from '../types';
import { AlertOctagon, CheckCircle, AlertTriangle, Info, ChevronDown, ChevronUp, FileText } from 'lucide-react';

interface RiskDashboardProps {
  analysis: DocumentAnalysis;
}

const RiskDashboard: React.FC<RiskDashboardProps> = ({ analysis }) => {
  const [showClauses, setShowClauses] = useState(true);

  const getRiskColor = (level: RiskLevel) => {
    switch (level) {
      case RiskLevel.SAFE: return 'text-emerald-400 border-emerald-500/50 bg-emerald-900/20';
      case RiskLevel.CAUTION: return 'text-yellow-400 border-yellow-500/50 bg-yellow-900/20';
      case RiskLevel.PREDATORY: return 'text-orange-500 border-orange-500/50 bg-orange-900/20';
      case RiskLevel.URGENT: return 'text-red-500 border-red-500/50 bg-red-900/20';
      default: return 'text-slate-400';
    }
  };

  const getRiskIcon = (level: RiskLevel) => {
    switch (level) {
      case RiskLevel.SAFE: return <CheckCircle className="w-8 h-8" />;
      case RiskLevel.CAUTION: return <Info className="w-8 h-8" />;
      case RiskLevel.PREDATORY: return <AlertTriangle className="w-8 h-8" />;
      case RiskLevel.URGENT: return <AlertOctagon className="w-8 h-8" />;
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto space-y-6 animate-fade-in">
      {/* Header Card */}
      <div className={`p-6 rounded-xl border ${getRiskColor(analysis.riskLevel)} flex flex-col md:flex-row items-start md:items-center justify-between gap-4`}>
        <div className="flex items-center gap-4">
          <div className="p-3 rounded-full bg-slate-900/50 shadow-inner">
            {getRiskIcon(analysis.riskLevel)}
          </div>
          <div>
            <h2 className="text-xl font-bold uppercase tracking-wider">{analysis.riskLevel} RISK DETECTED</h2>
            <p className="text-slate-300 opacity-90">{analysis.fileName}</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="text-right">
            <p className="text-xs text-slate-400 uppercase tracking-widest">Risk Score</p>
            <p className="text-4xl font-black">{analysis.riskScore}<span className="text-lg text-slate-500 font-normal">/100</span></p>
          </div>
          {/* Simple progress ring placeholder */}
          <div className="w-16 h-16 rounded-full border-4 border-slate-700 relative flex items-center justify-center">
            <div 
                className="absolute inset-0 rounded-full border-4 border-current opacity-40" 
                style={{ clipPath: `inset(${100 - analysis.riskScore}% 0 0 0)` }} // Simple visual hack for progress
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Main Analysis */}
        <div className="md:col-span-2 space-y-6">
          {/* Summary */}
          <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
            <h3 className="text-lg font-semibold text-white mb-3 flex items-center gap-2">
              <FileText size={20} className="text-blue-400" /> Executive Summary
            </h3>
            <p className="text-slate-300 leading-relaxed">{analysis.summary}</p>
          </div>

          {/* Clauses */}
          <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden">
            <div 
              className="p-6 flex items-center justify-between cursor-pointer hover:bg-slate-750 transition-colors"
              onClick={() => setShowClauses(!showClauses)}
            >
              <h3 className="text-lg font-semibold text-white flex items-center gap-2">
                <AlertTriangle size={20} className="text-orange-400" /> 
                Detected Clauses ({analysis.clauses.length})
              </h3>
              {showClauses ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
            </div>

            {showClauses && (
              <div className="px-6 pb-6 space-y-4">
                {analysis.clauses.map((clause, idx) => (
                  <div key={idx} className={`p-4 rounded-lg border ${clause.type === 'danger' ? 'border-red-900/50 bg-red-900/10' : 'border-slate-600 bg-slate-700/30'}`}>
                    <div className="flex items-start gap-3">
                      <div className={`mt-1 min-w-[8px] h-2 rounded-full ${clause.type === 'danger' ? 'bg-red-500' : 'bg-yellow-500'}`} />
                      <div>
                        <p className="text-slate-200 font-medium italic mb-2">"{clause.text}"</p>
                        <p className={`text-sm ${clause.type === 'danger' ? 'text-red-300' : 'text-slate-400'}`}>
                          <span className="font-bold uppercase text-xs mr-2 border px-1 rounded border-current opacity-70">
                            {clause.type}
                          </span>
                          {clause.explanation}
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
                {analysis.clauses.length === 0 && (
                   <p className="text-slate-500 italic">No specific dangerous clauses detected.</p>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Sidebar Actions */}
        <div className="space-y-6">
          {/* Actionable Advice */}
          <div className="bg-gradient-to-b from-blue-900/20 to-slate-800 p-6 rounded-xl border border-blue-800/50">
            <h3 className="text-lg font-bold text-blue-300 mb-3">AI Recommendation</h3>
            <p className="text-slate-300 text-sm leading-relaxed mb-4">
              {analysis.actionableAdvice}
            </p>
          </div>

          {/* Extracted Data */}
          <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
            <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-widest mb-4">Extracted Figures</h3>
            <div className="space-y-3">
              {analysis.extractedAmounts.map((item, idx) => (
                <div key={idx} className="flex justify-between items-center border-b border-slate-700 pb-2 last:border-0 last:pb-0">
                  <span className="text-slate-400 text-sm">{item.label}</span>
                  <span className="text-white font-mono font-bold">{item.amount}</span>
                </div>
              ))}
              {analysis.extractedAmounts.length === 0 && <span className="text-slate-500 text-sm">No amounts extracted.</span>}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RiskDashboard;

import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { simulateScenarioAdvice } from '../services/geminiService';
import { BrainCircuit, TrendingDown, TrendingUp, AlertCircle } from 'lucide-react';

const FinanceSimulator: React.FC = () => {
  // Inputs
  const [savings, setSavings] = useState(5000);
  const [expenses, setExpenses] = useState(2500);
  const [scenarioType, setScenarioType] = useState('job_loss'); // job_loss, inflation, rent_hike
  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [isLoadingAdvice, setIsLoadingAdvice] = useState(false);

  // Derived Data for Chart
  const [chartData, setChartData] = useState<any[]>([]);

  useEffect(() => {
    // Generate simple projection data based on inputs
    const months = 12;
    const data = [];
    let currentSavings = savings;

    // Scenario Multipliers
    let expenseMultiplier = 1.0;
    let income = 0; // Assuming job loss means 0 income for simplicity in this demo, or we could add an income input.
    // For this MVP, let's assume "Runway Simulator" where income stops or costs rise.

    if (scenarioType === 'inflation') {
       expenseMultiplier = 1.10; // 10% sudden inflation impact
       income = expenses * 1.05; // Assuming income matches old expenses roughly? Let's assume income stays same, expenses rise.
       // Actually, let's just model burn rate.
    } else if (scenarioType === 'rent_hike') {
       expenseMultiplier = 1.20;
    }

    // Let's refine the logic: Net Monthly Burn
    // Job Loss: Burn = Expenses. Income = 0.
    // Inflation: Burn = Expenses * 1.08 - Income (Assume Income = Expenses originally). Net = -0.08 * Expenses

    let burnRate = 0;

    if (scenarioType === 'job_loss') {
        burnRate = expenses;
    } else if (scenarioType === 'inflation') {
        burnRate = expenses * 0.15; // Gap created by inflation
    } else if (scenarioType === 'rent_hike') {
        burnRate = 500; // Flat increase
    }

    for (let i = 0; i <= months; i++) {
        data.push({
            month: `Month ${i}`,
            savings: Math.max(0, currentSavings),
            dangerZone: 0
        });
        currentSavings -= burnRate;
    }
    setChartData(data);

    // Debounced AI call could go here, but let's make it manual or effect-based
    const timer = setTimeout(async () => {
        setIsLoadingAdvice(true);
        const advice = await simulateScenarioAdvice(savings, expenses, scenarioType.replace('_', ' '));
        setAiAdvice(advice);
        setIsLoadingAdvice(false);
    }, 1000);

    return () => clearTimeout(timer);

  }, [savings, expenses, scenarioType]);

  return (
    <div className="w-full max-w-4xl mx-auto space-y-6">
      <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 shadow-xl">
        <div className="flex items-center gap-3 mb-6">
            <BrainCircuit className="text-purple-400" size={28} />
            <h2 className="text-2xl font-bold text-white">What-If Simulator</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {/* Controls */}
            <div className="space-y-6">
                <div>
                    <label className="block text-slate-400 text-sm mb-2">Current Savings ($)</label>
                    <input 
                        type="number" 
                        value={savings} 
                        onChange={(e) => setSavings(Number(e.target.value))}
                        className="w-full bg-slate-900 border border-slate-600 text-white rounded-lg p-3 focus:ring-2 focus:ring-purple-500 outline-none"
                    />
                </div>
                <div>
                    <label className="block text-slate-400 text-sm mb-2">Monthly Expenses ($)</label>
                    <input 
                        type="number" 
                        value={expenses} 
                        onChange={(e) => setExpenses(Number(e.target.value))}
                        className="w-full bg-slate-900 border border-slate-600 text-white rounded-lg p-3 focus:ring-2 focus:ring-purple-500 outline-none"
                    />
                </div>
                <div>
                    <label className="block text-slate-400 text-sm mb-2">Disaster Scenario</label>
                    <select 
                        value={scenarioType}
                        onChange={(e) => setScenarioType(e.target.value)}
                        className="w-full bg-slate-900 border border-slate-600 text-white rounded-lg p-3 focus:ring-2 focus:ring-purple-500 outline-none"
                    >
                        <option value="job_loss">Sudden Job Loss</option>
                        <option value="inflation">High Inflation (15% Cost Increase)</option>
                        <option value="rent_hike">Rent Hike ($500/mo)</option>
                    </select>
                </div>
            </div>

            {/* Chart */}
            <div className="md:col-span-2 min-h-[300px] bg-slate-900/50 rounded-xl p-4 border border-slate-700/50">
                <h3 className="text-slate-400 text-sm font-semibold mb-4 text-center uppercase tracking-wider">Projected Runway</h3>
                <ResponsiveContainer width="100%" height={250}>
                    <LineChart data={chartData}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                        <XAxis dataKey="month" stroke="#94a3b8" fontSize={12} tickMargin={10} />
                        <YAxis stroke="#94a3b8" fontSize={12} />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#1e293b', borderColor: '#475569', color: '#f1f5f9' }} 
                            itemStyle={{ color: '#f1f5f9' }}
                        />
                        <Legend />
                        <Line type="monotone" dataKey="savings" stroke="#a855f7" strokeWidth={3} dot={{ r: 4 }} activeDot={{ r: 8 }} name="Savings Balance" />
                    </LineChart>
                </ResponsiveContainer>

                {/* Insights */}
                <div className="mt-4 flex items-start gap-3 p-3 bg-purple-900/20 border border-purple-500/30 rounded-lg">
                    {isLoadingAdvice ? (
                        <span className="text-slate-400 text-sm animate-pulse">AI is calculating survival strategy...</span>
                    ) : (
                        <>
                            <AlertCircle className="text-purple-400 min-w-[20px]" size={20} />
                            <p className="text-sm text-purple-200">{aiAdvice}</p>
                        </>
                    )}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default FinanceSimulator;

import React, { useState } from 'react';
import { generateNegotiationContent } from '../services/geminiService';
import { DocumentAnalysis } from '../types';
import { Mail, PhoneCall, Copy, Check, MessageSquare } from 'lucide-react';

interface NegotiationHubProps {
  currentDoc: DocumentAnalysis | null;
}

const NegotiationHub: React.FC<NegotiationHubProps> = ({ currentDoc }) => {
  const [activeTab, setActiveTab] = useState<'script' | 'email'>('script');
  const [goal, setGoal] = useState('Waive the late fee');
  const [generatedContent, setGeneratedContent] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleGenerate = async () => {
    if (!currentDoc) return;
    setIsGenerating(true);
    const content = await generateNegotiationContent(currentDoc, activeTab, goal);
    setGeneratedContent(content);
    setIsGenerating(false);
    setCopied(false);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(generatedContent);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (!currentDoc) {
    return (
      <div className="text-center p-12 bg-slate-800 rounded-xl border border-slate-700 border-dashed">
        <MessageSquare className="mx-auto h-12 w-12 text-slate-600 mb-4" />
        <h3 className="text-xl font-medium text-slate-300">No Document Selected</h3>
        <p className="text-slate-500 mt-2">Scan a document first to generate specific negotiation strategies.</p>
      </div>
    );
  }

  return (
    <div className="w-full max-w-4xl mx-auto">
       <div className="bg-slate-800 rounded-xl border border-slate-700 shadow-xl overflow-hidden">
         {/* Header */}
         <div className="bg-slate-900/50 p-6 border-b border-slate-700">
            <h2 className="text-2xl font-bold text-white mb-2">Negotiation Assistant</h2>
            <p className="text-slate-400 text-sm">Target: <span className="text-white font-semibold">{currentDoc.fileName}</span></p>
         </div>

         <div className="p-6 grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Controls */}
            <div className="space-y-6">
                <div>
                    <label className="block text-slate-400 text-sm font-semibold mb-3">Strategy Type</label>
                    <div className="flex bg-slate-900 p-1 rounded-lg">
                        <button 
                            onClick={() => setActiveTab('script')}
                            className={`flex-1 py-2 px-4 rounded-md flex items-center justify-center gap-2 transition-all ${activeTab === 'script' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}
                        >
                            <PhoneCall size={18} /> Call Script
                        </button>
                        <button 
                            onClick={() => setActiveTab('email')}
                            className={`flex-1 py-2 px-4 rounded-md flex items-center justify-center gap-2 transition-all ${activeTab === 'email' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}
                        >
                            <Mail size={18} /> Formal Email
                        </button>
                    </div>
                </div>

                <div>
