                                </div>
                            </div>
                        </div>

                        {/* Amount Section */}
                        <div className="text-right min-w-[100px]">
                            <p className="text-2xl font-bold text-white tracking-tight">
                                {settings.currencySymbol}{task.amount.toFixed(2)}
                            </p>
                            <p className="text-xs text-slate-500 uppercase tracking-wide">{task.category}</p>
                        </div>

                        {/* Actions */}
                        <div className="flex items-center gap-2 border-l border-slate-700 pl-4 ml-2">
                             {activeTab === 'pending' && (
                                <>
                                    <button 
                                        onClick={() => initiateCompletion(task.id)}
                                        className="p-2 bg-emerald-600/10 hover:bg-emerald-600 text-emerald-500 hover:text-white rounded-lg transition-colors tooltip"
                                        title="Mark Complete"
                                    >
                                        <CheckCircle size={20} />
                                    </button>
                                    <button 
                                        onClick={() => onNegotiate(task)}
                                        className="p-2 bg-purple-600/10 hover:bg-purple-600 text-purple-400 hover:text-white rounded-lg transition-colors"
                                        title="Negotiate"
                                    >
                                        <FileText size={20} />
                                    </button>
                                    <button 
                                        onClick={() => handleDelete(task.id)}
                                        className="p-2 text-slate-500 hover:bg-red-900/20 hover:text-red-400 rounded-lg transition-colors"
                                    >
                                        <Trash2 size={20} />
                                    </button>
                                </>
                             )}
                             {activeTab === 'completed' && (
                                 <div className="flex items-center gap-4">
                                    {task.proofOfPayment && (
                                        <span className="text-xs text-emerald-400 flex items-center gap-1">
                                            <FileText size={14} /> Proof Attached
                                        </span>
                                    )}
                                    <button 
                                        onClick={() => handleDelete(task.id)}
                                        className="p-2 text-slate-500 hover:bg-red-900/20 hover:text-red-400 rounded-lg transition-colors"
                                    >
                                        <Trash2 size={20} />
                                    </button>
                                 </div>
                             )}
                        </div>
                    </div>
                </div>
            ))
        )}
      </div>

      {/* Hidden File Input for Proof */}
      <input type="file" ref={fileInputRef} onChange={handleProofUpload} className="hidden" accept="image/*" />

      {/* Settings Modal */}
      {settingsOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
            <div className="w-full max-w-md bg-slate-900 border border-slate-700 rounded-2xl p-6 shadow-2xl">
                <h3 className="text-xl font-bold text-white mb-4">Retention Settings</h3>

                <div className="space-y-4">
                    <div>
                        <label className="block text-sm text-slate-400 mb-2">Delete completed items after (days)</label>
                        <input 
                            type="number" 
                            value={settings.deleteCompletedAfterDays}
                            onChange={(e) => setSettings({...settings, deleteCompletedAfterDays: parseInt(e.target.value)})}
                            className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-white"
                        />
                        <p className="text-xs text-slate-500 mt-1">Set to 0 to keep forever.</p>
                    </div>
                    <div>
                        <label className="block text-sm text-slate-400 mb-2">Currency Symbol</label>
                        <input 
                            type="text" 
                            value={settings.currencySymbol}
                            onChange={(e) => setSettings({...settings, currencySymbol: e.target.value})}
                            className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-white"
                        />
                    </div>
                </div>

                <div className="mt-6 flex justify-end gap-3">
                    <button onClick={() => setSettingsOpen(false)} className="px-4 py-2 text-slate-400 hover:text-white">Cancel</button>
                    <button onClick={handleSaveSettings} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-500">Save Changes</button>
                </div>
            </div>
        </div>
      )}

    </div>
  );
};

export default TriageCenter;

import React, { useState } from 'react';
import { DocumentAnalysis, RiskLevel } from '../types';
import { AlertOctagon, CheckCircle, AlertTriangle, Info, ChevronDown, ChevronUp, FileText, PlusCircle } from 'lucide-react';
import DebtFormModal from './DebtFormModal';

interface RiskDashboardProps {
  analysis: DocumentAnalysis;
  onSaveToTriage: (analysis: DocumentAnalysis) => void;
}

const RiskDashboard: React.FC<RiskDashboardProps> = ({ analysis, onSaveToTriage }) => {
  const [showClauses, setShowClauses] = useState(true);

  const getRiskColor = (level: RiskLevel) => {
    switch (level) {
      case RiskLevel.SAFE: return 'text-emerald-400 border-emerald-500/50 bg-emerald-900/20';
      case RiskLevel.CAUTION: return 'text-yellow-400 border-yellow-500/50 bg-yellow-900/20';
      case RiskLevel.PREDATORY: return 'text-orange-500 border-orange-500/50 bg-orange-900/20';
      case RiskLevel.URGENT: return 'text-red-500 border-red-500/50 bg-red-900/20';
      default: return 'text-slate-400';
    }
  };

  const getRiskIcon = (level: RiskLevel) => {
    switch (level) {
      case RiskLevel.SAFE: return <CheckCircle className="w-8 h-8" />;
      case RiskLevel.CAUTION: return <Info className="w-8 h-8" />;
      case RiskLevel.PREDATORY: return <AlertTriangle className="w-8 h-8" />;
      case RiskLevel.URGENT: return <AlertOctagon className="w-8 h-8" />;
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto space-y-6 animate-fade-in">
      {/* Header Card */}
      <div className={`p-6 rounded-xl border ${getRiskColor(analysis.riskLevel)} flex flex-col md:flex-row items-start md:items-center justify-between gap-4`}>
        <div className="flex items-center gap-4">
          <div className="p-3 rounded-full bg-slate-900/50 shadow-inner">
            {getRiskIcon(analysis.riskLevel)}
          </div>
          <div>
            <h2 className="text-xl font-bold uppercase tracking-wider">{analysis.riskLevel} RISK DETECTED</h2>
            <p className="text-slate-300 opacity-90">{analysis.fileName}</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="text-right">
            <p className="text-xs text-slate-400 uppercase tracking-widest">Risk Score</p>
            <p className="text-4xl font-black">{analysis.riskScore}<span className="text-lg text-slate-500 font-normal">/100</span></p>
          </div>
          {/* Simple progress ring placeholder */}
          <div className="w-16 h-16 rounded-full border-4 border-slate-700 relative flex items-center justify-center">
            <div 
                className="absolute inset-0 rounded-full border-4 border-current opacity-40" 
                style={{ clipPath: `inset(${100 - analysis.riskScore}% 0 0 0)` }} // Simple visual hack for progress
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Main Analysis */}
        <div className="md:col-span-2 space-y-6">
          {/* Summary */}
          <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
            <h3 className="text-lg font-semibold text-white mb-3 flex items-center gap-2">
              <FileText size={20} className="text-blue-400" /> Executive Summary
            </h3>
            <p className="text-slate-300 leading-relaxed">{analysis.summary}</p>
          </div>

          {/* Clauses */}
          <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden">
            <div 
              className="p-6 flex items-center justify-between cursor-pointer hover:bg-slate-750 transition-colors"
              onClick={() => setShowClauses(!showClauses)}
            >
              <h3 className="text-lg font-semibold text-white flex items-center gap-2">
                <AlertTriangle size={20} className="text-orange-400" /> 
                Detected Clauses ({analysis.clauses.length})
              </h3>
              {showClauses ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
            </div>

            {showClauses && (
              <div className="px-6 pb-6 space-y-4">
                {analysis.clauses.map((clause, idx) => (
                  <div key={idx} className={`p-4 rounded-lg border ${clause.type === 'danger' ? 'border-red-900/50 bg-red-900/10' : 'border-slate-600 bg-slate-700/30'}`}>
                    <div className="flex items-start gap-3">
                      <div className={`mt-1 min-w-[8px] h-2 rounded-full ${clause.type === 'danger' ? 'bg-red-500' : 'bg-yellow-500'}`} />
                      <div>
                        <p className="text-slate-200 font-medium italic mb-2">"{clause.text}"</p>
                        <p className={`text-sm ${clause.type === 'danger' ? 'text-red-300' : 'text-slate-400'}`}>
                          <span className="font-bold uppercase text-xs mr-2 border px-1 rounded border-current opacity-70">
                            {clause.type}
                          </span>
                          {clause.explanation}
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
                {analysis.clauses.length === 0 && (
                   <p className="text-slate-500 italic">No specific dangerous clauses detected.</p>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Sidebar Actions */}
        <div className="space-y-6">

          {/* Primary Action */}
          <button 
             onClick={() => onSaveToTriage(analysis)}
             className="w-full py-4 bg-gradient-to-r from-blue-600 to-blue-500 hover:from-blue-500 hover:to-blue-400 text-white rounded-xl font-bold shadow-lg shadow-blue-900/20 transition-all transform hover:-translate-y-0.5 flex items-center justify-center gap-2"
          >
             <PlusCircle size={20} />
             Track in Triage Center
          </button>

          {/* Actionable Advice */}
          <div className="bg-gradient-to-b from-blue-900/20 to-slate-800 p-6 rounded-xl border border-blue-800/50">
            <h3 className="text-lg font-bold text-blue-300 mb-3">AI Recommendation</h3>
            <p className="text-slate-300 text-sm leading-relaxed mb-4">
              {analysis.actionableAdvice}
            </p>
          </div>

          {/* Extracted Data */}
          <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
            <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-widest mb-4">Extracted Figures</h3>
            <div className="space-y-3">
              {analysis.extractedAmounts.map((item, idx) => (
                <div key={idx} className="flex justify-between items-center border-b border-slate-700 pb-2 last:border-0 last:pb-0">
                  <span className="text-slate-400 text-sm">{item.label}</span>
                  <span className="text-white font-mono font-bold">{item.amount}</span>
                </div>
              ))}
              {analysis.extractedAmounts.length === 0 && <span className="text-slate-500 text-sm">No amounts extracted.</span>}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RiskDashboard;

import React, { useState, useEffect } from 'react';
import { DocumentAnalysis, User, DebtTask } from './types';
import DocumentScanner from './components/DocumentScanner';
import RiskDashboard from './components/RiskDashboard';
import FinanceSimulator from './components/FinanceSimulator';
import NegotiationHub from './components/NegotiationHub';
import AuthPage from './components/AuthPage';
import TriageCenter from './components/TriageCenter';
import DebtFormModal from './components/DebtFormModal';
import { authService } from './services/authService';
import { debtService } from './services/debtService';
import { Shield, FileText, Activity, MessageSquare, Menu, X, LayoutDashboard, LogOut, User as UserIcon, ListTodo } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<'scan' | 'triage' | 'dashboard' | 'simulator' | 'negotiate'>('scan');
  const [documents, setDocuments] = useState<DocumentAnalysis[]>([]);
  const [selectedDocId, setSelectedDocId] = useState<string | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Debt Form Modal State
  const [isDebtModalOpen, setIsDebtModalOpen] = useState(false);
  const [docToSave, setDocToSave] = useState<DocumentAnalysis | null>(null);

  // Negotiation Context State
  const [negotiationTask, setNegotiationTask] = useState<DebtTask | null>(null);

  // Check for existing session on load
  useEffect(() => {
    const user = authService.getCurrentUser();
    if (user) {
        setCurrentUser(user);
    }
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    authService.logout();
    setCurrentUser(null);
    setDocuments([]);
    setSelectedDocId(null);
    setCurrentView('scan');
  };

  const handleAnalysisComplete = (analysis: DocumentAnalysis) => {
    setDocuments(prev => [analysis, ...prev]);
    setSelectedDocId(analysis.id);
    setCurrentView('dashboard'); // Show Risk Dashboard first
  };

  const handleOpenSaveModal = (analysis: DocumentAnalysis) => {
      setDocToSave(analysis);
      setIsDebtModalOpen(true);
  };

  const handleSaveDebt = (taskData: any) => {
      if (currentUser) {
          debtService.addDebt(currentUser.id, taskData);
          setIsDebtModalOpen(false);
          setCurrentView('triage');
      }
  };

  const handleNavigateToNegotiate = (task: DebtTask) => {
      // Create a mock doc analysis context from the task if actual doc is missing from RAM
      const relatedDoc = documents.find(d => d.id === task.analysisId);

      if (relatedDoc) {
          setSelectedDocId(relatedDoc.id);
      } else {
          // Fallback if we refreshed and lost the scan result
          const mockDoc: DocumentAnalysis = {
              id: task.analysisId || 'mock',
              fileName: task.title,
              timestamp: task.createdAt,
              summary: task.notes,
              riskScore: task.riskLevel === 'PREDATORY' ? 85 : 20,
              riskLevel: task.riskLevel,
              clauses: [],
              extractedAmounts: [{ label: 'Amount', amount: String(task.amount) }],
              actionableAdvice: 'Proceed with negotiation based on saved task parameters.'
          };
          setDocuments(prev => [mockDoc, ...prev]);
          setSelectedDocId(mockDoc.id);
      }

      setCurrentView('negotiate');
  };

  const currentDoc = documents.find(d => d.id === selectedDocId) || documents[0] || null;

  const NavItem = ({ view, icon, label }: { view: typeof currentView, icon: React.ReactNode, label: string }) => (
    <button
      onClick={() => {
        setCurrentView(view);
        setIsMobileMenuOpen(false);
      }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200 ${
        currentView === view 
          ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' 
          : 'text-slate-400 hover:bg-slate-800 hover:text-white'
      }`}
    >
      {icon}
      <span className="font-medium">{label}</span>
    </button>
  );

  // If not logged in, show Auth Page
  if (!currentUser) {
    return <AuthPage onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30">

      {/* Mobile Header */}
      <div className="lg:hidden p-4 bg-slate-900 border-b border-slate-800 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-2">
            <Shield className="text-emerald-500" />
            <span className="font-bold text-lg text-white">Debt Hunter</span>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="text-slate-300">
            {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      <div className="flex flex-col lg:flex-row min-h-screen">

        {/* Sidebar */}
        <aside className={`
            fixed lg:sticky top-16 lg:top-0 left-0 h-[calc(100vh-64px)] lg:h-screen w-full lg:w-72 bg-slate-900 border-r border-slate-800 p-6 flex flex-col z-40 transition-transform duration-300 ease-in-out
            ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        `}>
          <div className="hidden lg:flex items-center gap-3 mb-10 px-2">
            <div className="w-10 h-10 bg-emerald-500/10 rounded-lg flex items-center justify-center border border-emerald-500/20">
                <Shield className="text-emerald-500" size={24} />
            </div>
            <div>
                <h1 className="font-bold text-xl text-white tracking-tight">Predatory<br/>Debt Hunter</h1>
            </div>
          </div>

          <nav className="space-y-2 flex-1">
            <NavItem view="scan" icon={<FileText size={20} />} label="Scanner" />
            <NavItem view="triage" icon={<ListTodo size={20} />} label="Triage Center" />
            {currentDoc && <NavItem view="dashboard" icon={<LayoutDashboard size={20} />} label="Risk Analysis" />}
            <NavItem view="simulator" icon={<Activity size={20} />} label="Simulator" />
            <NavItem view="negotiate" icon={<MessageSquare size={20} />} label="Negotiation" />
          </nav>

          {/* User Profile & Logout */}
          <div className="mt-8 pt-6 border-t border-slate-800">
             <div className="flex items-center gap-3 px-2 mb-4">
                <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center text-slate-400">
                    <UserIcon size={16} />
                </div>
                <div className="flex-1 overflow-hidden">
                    <p className="text-sm font-semibold text-white truncate">{currentUser.name}</p>
                    <p className="text-xs text-slate-500 truncate">{currentUser.email}</p>
                </div>
             </div>
             <button 
                onClick={handleLogout}
                className="w-full flex items-center gap-2 px-4 py-2 text-sm text-red-400 hover:bg-red-950/30 hover:text-red-300 rounded-lg transition-colors"
             >
                <LogOut size={16} /> Sign Out
             </button>
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 p-4 lg:p-8 lg:ml-0 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {currentView === 'scan' && (
              <div className="animate-in fade-in zoom-in duration-300">
                <div className="mb-8">
                    <h2 className="text-3xl font-bold text-white mb-2">Scan & Analyze</h2>
                    <p className="text-slate-400">Upload financial documents to detect predatory terms instantly.</p>
                </div>
                <DocumentScanner onAnalysisComplete={handleAnalysisComplete} />
              </div>
            )}

            {currentView === 'triage' && (
                <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                    <TriageCenter 
                        user={currentUser} 
                        onNegotiate={handleNavigateToNegotiate}
                        onOpenDoc={(id) => { setSelectedDocId(id); setCurrentView('dashboard'); }}
                    />
                </div>
            )}

            {currentView === 'dashboard' && (
               currentDoc ? (
                 <RiskDashboard 
                    analysis={currentDoc} 
                    onSaveToTriage={handleOpenSaveModal}
                 />
               ) : (
                 <div className="flex flex-col items-center justify-center h-[60vh] text-center">
                    <Shield size={64} className="text-slate-700 mb-4" />
                    <h2 className="text-xl font-bold text-slate-400">No Analysis Available</h2>
                    <p className="text-slate-500 mt-2 mb-6">Scan a document to view the risk dashboard.</p>
                    <button 
                        onClick={() => setCurrentView('scan')}
                        className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-500 transition-colors"
                    >
                        Go to Scanner
                    </button>
                 </div>
               )
            )}

            {currentView === 'simulator' && (
                <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                    <FinanceSimulator user={currentUser} />
                </div>
            )}

            {currentView === 'negotiate' && (
                <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                    <NegotiationHub currentDoc={currentDoc} />
                </div>
            )}
          </div>
        </main>
      </div>

      {/* Modals */}
      {docToSave && (
          <DebtFormModal 
              isOpen={isDebtModalOpen} 
              onClose={() => setIsDebtModalOpen(false)} 
              analysis={docToSave}
              onSave={handleSaveDebt}
          />
      )}
    </div>
  );
};

export default App;

