import React, { useState, useEffect } from 'react';
import { DebtTask } from './debtService';

interface DebtFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (debtTask: DebtTask) => void;
  analysis: any;
}

const DebtFormModal: React.FC<DebtFormModalProps> = ({ isOpen, onClose, onSave, analysis }) => {
  const [formData, setFormData] = useState({
    title: '',
    issuer: '',
    amount: '0',
    dueDate: '',
    category: 'bill',
    priority: 'normal',
    notes: '',
  });

  useEffect(() => {
    if (isOpen && analysis) {
      const amountObj = analysis.entities.find((a: any) => a.label.toLowerCase().includes('total') || a.label.toLowerCase().includes('due'));
      const rawAmount = amountObj ? amountObj.amount.replace(/[^0-9.]/g, '') : '0';

      setFormData({
        title: `Processed: ${analysis.fileName}`,
        issuer: 'Unknown Issuer', // AI would ideally extract this specifically
        amount: rawAmount,
        dueDate: '', // AI date extraction placeholder
        category: analysis.riskLevel === 'PREDATORY' ? 'loan' : 'bill',
        priority: analysis.riskLevel === 'URGENT' ? 'urgent' : 'normal',
        notes: analysis.summary,
      });
    }
  }, [isOpen, analysis]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      title: formData.title,
      issuer: formData.issuer,
      amount: parseFloat(formData.amount) || 0,
